/**
 * The families this product ships, as **one** table (ADR 0055).
 *
 * Until sprint 29 the gallery was four parallel copies of eight names — the tokens' `GALLERY_FAMILIES`,
 * the renderer's `SHIPPABLE_FAMILIES`, the publisher's `FONT_SOURCES` and the generated bytes — held
 * level by tests. Every other name in those copies was already a pure function of the family's own
 * name: the file is `<slug>-latin-<weight>-normal.woff2`, the package `@fontsource/<slug>`, the licence
 * `fonts/OFL-<Name>.txt`. So the copies become derivations, and what is written by hand is this list.
 *
 * **Why schema, of all places.** It is not a document type and is not part of `documentSchema`, so the
 * snapshot does not move. It lives here because it is the one package every reader may import: the
 * renderer admits only `@retorika/schema` and `@retorika/catalog` (everything there travels to the
 * client's site), tokens admits only schema, and tokens cannot import the renderer because the
 * renderer's own tests import tokens — a cycle under `tsc --build`. Catalog is about sections, so it
 * would be the wrong owner. The renderer still owns the derivation of faces and the only `url()`.
 *
 * **The safety property does not change.** A document *chooses* a row by exact equality of its stack's
 * first family and can never *name* a file; nothing here is read from a document.
 */

/**
 * The species a family is filed under, which the chooser filters by and which decides the generic
 * keyword its stack ends in.
 *
 * `slab` and `display` are ours rather than Google's: Google files a slab serif under `serif` and many
 * headline families under `sans-serif`, and «de cartel» is a judgement about where a family is meant to
 * be used, not a property of its outlines.
 */
export const FONT_KINDS = ["sans", "serif", "slab", "display"] as const;
export type FontKind = (typeof FONT_KINDS)[number];

/**
 * The generic keyword each species falls back to, so a visitor whose browser fetched no face at all
 * still gets a serif where a serif was chosen. A slab is a serif; a headline family is set as a sans
 * when it does not arrive, because a display serif would have to pass filter 3 like any other and the
 * survey found none that did.
 */
export const GENERIC_OF: Readonly<Record<FontKind, "sans-serif" | "serif">> = {
  sans: "sans-serif",
  serif: "serif",
  slab: "serif",
  display: "sans-serif",
};

/**
 * The shape a family name must have to be written into CSS: ASCII letters and digits in
 * space-separated words, no apostrophe, no hyphen, no accent.
 *
 * Moved here from `packages/renderer/src/escape.ts` in sprint 29, which imports it: it is both the
 * renderer's lock on what it emits and filter 4 of ADR 0046 §3 on what may enter this table, and
 * `scripts/survey-fonts.ts` applies it to every candidate. One pattern, so the filter and the lock
 * cannot disagree.
 */
export const FONT_FAMILY_PATTERN = /^[A-Za-z][A-Za-z0-9]*(?: [A-Za-z0-9]+)*$/;

/**
 * A family's `@fontsource` id, which is also the stem of every file name derived from it:
 * «EB Garamond» → `eb-garamond`, «Source Sans 3» → `source-sans-3`.
 *
 * Throws on a name the pattern refuses, so a row that could never be emitted cannot quietly produce a
 * slug either.
 */
export function fontFamilySlug(family: string): string {
  if (!FONT_FAMILY_PATTERN.test(family)) {
    throw new Error(`fontFamilySlug: "${family}" is not a family name this product can emit`);
  }
  return family.toLowerCase().replaceAll(" ", "-");
}

/**
 * One family this product ships: its name, its species, and the row that would take its place.
 *
 * **`substitute` is David's condition for every row** (27 October 2026): the closest family **of the
 * same species already in this table**, written when the row enters rather than argued when it
 * leaves. A theme stores the resolved stack, so retiring a family is a migration — `0012` for
 * Playfair Display, `0014` for Libre Baskerville — and with the substitute written down that
 * migration is mechanical: the retiring row's whole stack becomes its substitute's.
 */
export interface FontGalleryRow {
  /** The family's name, exactly as `@fontsource`'s `metadata.json` and the stylesheet spell it. */
  family: string;
  kind: FontKind;
  /** Another row's `family`, of the same `kind`. */
  substitute: string;
}

/**
 * The gallery, **alphabetical**: the order the chooser lists and the order a published page emits its
 * `@font-face` rules in, which `INV_5` and the golden corpus depend on.
 *
 * Every row passed the four filters of ADR 0046 §3 in the survey of 27 October 2026
 * (`pnpm fonts:survey`, recorded in ADR 0055) — with filter 2 read from the holders' own licences and
 * from the author's repository, never from the package (ADR 0045, amended). Day 2 of sprint 29 is
 * twenty-five rows: fourteen sans, which is the whole of the composition's sans quota, seven serifs
 * and four slabs. «De cartel» enters on day 3.
 *
 * **Inter, Roboto and Open Sans are near neighbours**, and David asked that each one's substitute be
 * found among the other two: Inter and Roboto name each other, Open Sans names Roboto.
 */
export const FONT_GALLERY: readonly FontGalleryRow[] = [
  { family: "Aleo", kind: "slab", substitute: "Bitter" },
  { family: "Bitter", kind: "slab", substitute: "Zilla Slab" },
  { family: "Crimson Pro", kind: "serif", substitute: "EB Garamond" },
  // DM Sans was drawn from Poppins, and Poppins is the closest thing to it in any table.
  { family: "DM Sans", kind: "sans", substitute: "Poppins" },
  { family: "EB Garamond", kind: "serif", substitute: "Crimson Pro" },
  { family: "Figtree", kind: "sans", substitute: "DM Sans" },
  { family: "Fraunces", kind: "serif", substitute: "Crimson Pro" },
  // Gelasio stands on Georgia's metrics; the text serif nearest it in build and colour is the Caslon.
  { family: "Gelasio", kind: "serif", substitute: "Libre Caslon Text" },
  { family: "Inter", kind: "sans", substitute: "Roboto" },
  { family: "Karla", kind: "sans", substitute: "Work Sans" },
  { family: "Libre Caslon Text", kind: "serif", substitute: "EB Garamond" },
  // Public Sans was drawn from Libre Franklin, so the two name each other.
  { family: "Libre Franklin", kind: "sans", substitute: "Public Sans" },
  { family: "Manrope", kind: "sans", substitute: "Figtree" },
  { family: "Montserrat", kind: "sans", substitute: "Poppins" },
  { family: "Newsreader", kind: "serif", substitute: "Spectral" },
  { family: "Nunito Sans", kind: "sans", substitute: "Figtree" },
  { family: "Open Sans", kind: "sans", substitute: "Roboto" },
  { family: "Poppins", kind: "sans", substitute: "Montserrat" },
  { family: "Public Sans", kind: "sans", substitute: "Libre Franklin" },
  { family: "Roboto", kind: "sans", substitute: "Inter" },
  { family: "Rokkitt", kind: "slab", substitute: "Zilla Slab" },
  { family: "Rubik", kind: "sans", substitute: "Nunito Sans" },
  { family: "Spectral", kind: "serif", substitute: "Newsreader" },
  { family: "Work Sans", kind: "sans", substitute: "Karla" },
  { family: "Zilla Slab", kind: "slab", substitute: "Bitter" },
];
